#include <cstddef>
#include <iostream>
#include <memory>
#include <utility>

template <typename T>
class Vec
{
public:
    void push_back(T value) {}
    std::size_t size() const { return m_size; }

private:
    std::unique_ptr<T[]> m_data{};
    std::size_t m_size{}, m_capacity{};
};

int main()
{
    Vec<int> v{};
    for (int i{1}; i <= 10; ++i) v.push_back(i);
}
